package emulator

import (
	"sort"
	"strings"
)

// cfn_schema.go reads the CloudFormation resource specification substrate vendors (#1605).
//
// The table itself, cfnSchemaTypes, is generated by cmd/gen-cfn-schema from a stripped copy
// of the us-east-1 specification under emulator/cfnschema, and is what decides two of
// CloudFormation's own refusals: a resource type the specification does not list is
// "Unrecognized", and a top-level property its type does not declare is "extraneous". See
// cfn_validate.go for both.

// cfnSchemaKind is the kind of value a property takes or an attribute answers, as the
// specification declares it: a primitive type, or a list, a map or a property type (an
// object).
type cfnSchemaKind uint8

// The kinds the specification uses. The generator refuses a kind not listed here.
const (
	cfnKindString cfnSchemaKind = iota
	cfnKindInteger
	cfnKindLong
	cfnKindDouble
	cfnKindBoolean
	cfnKindTimestamp
	cfnKindJSON
	cfnKindList
	cfnKindMap
	cfnKindObject
)

// cfnSchemaProperty is one top-level property a resource type declares.
type cfnSchemaProperty struct {
	Name     string
	Required bool
	Kind     cfnSchemaKind
}

// cfnSchemaAttribute is one Fn::GetAtt attribute a resource type publishes.
type cfnSchemaAttribute struct {
	Name string
	Kind cfnSchemaKind
}

// cfnSchemaType is one resource type in the specification. Properties and Attributes are
// sorted by name.
type cfnSchemaType struct {
	Name       string
	Properties []cfnSchemaProperty
	Attributes []cfnSchemaAttribute
}

// cfnSchemaLookup returns the specification's entry for a resource type.
func cfnSchemaLookup(typ string) (*cfnSchemaType, bool) {
	i := sort.Search(len(cfnSchemaTypes), func(i int) bool { return cfnSchemaTypes[i].Name >= typ })
	if i < len(cfnSchemaTypes) && cfnSchemaTypes[i].Name == typ {
		return &cfnSchemaTypes[i], true
	}
	return nil, false
}

// property returns the named top-level property's declaration.
func (t *cfnSchemaType) property(name string) (cfnSchemaProperty, bool) {
	i := sort.Search(len(t.Properties), func(i int) bool { return t.Properties[i].Name >= name })
	if i < len(t.Properties) && t.Properties[i].Name == name {
		return t.Properties[i], true
	}
	return cfnSchemaProperty{}, false
}

// attribute returns the named Fn::GetAtt attribute's declaration.
func (t *cfnSchemaType) attribute(name string) (cfnSchemaAttribute, bool) {
	i := sort.Search(len(t.Attributes), func(i int) bool { return t.Attributes[i].Name >= name })
	if i < len(t.Attributes) && t.Attributes[i].Name == name {
		return t.Attributes[i], true
	}
	return cfnSchemaAttribute{}, false
}

// cfnCustomResourceType reports whether typ is a custom resource: AWS::CloudFormation::CustomResource
// or a Custom:: type. A custom resource's properties are whatever its provider reads, so
// the specification cannot say any of them is extraneous, and Custom::* names are the
// template author's own, so the specification cannot list them.
func cfnCustomResourceType(typ string) bool {
	return typ == "AWS::CloudFormation::CustomResource" || strings.HasPrefix(typ, "Custom::")
}

// cfnRecognizedType reports whether CloudFormation recognizes a resource type: one the
// specification lists, a custom resource, AWS::CDK::Metadata, or a third-party, private-registry
// or module type ([cfnThirdPartyType]).
//
// AWS::CDK::Metadata is the record the CDK adds to every stack it synthesizes, and
// CloudFormation accepts it, but the specification does not list it — it is not a resource
// type in the registry sense. Leaving it out would refuse every CDK-synthesized template.
//
// A third-party or private registry type (Datadog::Monitors::Monitor, MongoDB::Atlas::Cluster,
// MyOrg::Service::Thing) and a module (Org::Service::Name::MODULE) are recognized by an account
// that has activated or registered them, which substrate cannot know, so they are not refused
// as unrecognized: strict mode refuses them as unemulated, and lenient mode stubs them. The
// specification lists only AWS's own types, so every other name is checked against it — which is
// what refuses a misspelled AWS name such as AWS:EC2::VPC or Aws::S3::Bucket.
func cfnRecognizedType(typ string) bool {
	if typ == cfnCDKMetadataType || cfnCustomResourceType(typ) || cfnThirdPartyType(typ) {
		return true
	}
	_, ok := cfnSchemaLookup(typ)
	return ok
}

// cfnThirdPartyType reports whether typ has the shape of a type another publisher or the account
// itself registers: Organization::Service::Resource — exactly three non-empty "::"-separated
// segments with no stray colon — or Organization::Service::Resource::MODULE, as the registry's
// type-name rule writes them, under an organization that is not AWS's. A first segment that is AWS
// or Alexa in any case is AWS's namespace, reserved to it, so a name there is AWS's to recognize:
// Aws::S3::Bucket is a misspelling, not a third-party type.
func cfnThirdPartyType(typ string) bool {
	segs := strings.Split(typ, "::")
	switch {
	case len(segs) == 3:
	case len(segs) == 4 && segs[3] == "MODULE":
	default:
		return false
	}
	for _, s := range segs {
		if s == "" || strings.Contains(s, ":") {
			return false
		}
	}
	org := strings.ToLower(segs[0])
	return org != "aws" && org != "alexa"
}

// cfnAttributeIsList reports whether the specification declares a type's attribute as a
// list, which is what lets Fn::GetAtt answer it into Fn::Select, Fn::Join or a list
// property.
func cfnAttributeIsList(typ, attr string) bool {
	t, ok := cfnSchemaLookup(typ)
	if !ok {
		return false
	}
	a, ok := t.attribute(attr)
	return ok && a.Kind == cfnKindList
}
